 const subjectValue=Object.prototype.hasOwnProperty.call(draft,'subject')?draft.subject:display(subject,''),rateValue=Object.prototype.hasOwnProperty.call(draft,'final_rate')?draft.final_rate:display(rate,''),deliveryValue=Object.prototype.hasOwnProperty.call(draft,'delivery')?draft.delivery:'__unchanged',bikValue=Object.prototype.hasOwnProperty.call(draft,'bik')?draft.bik:display(bik,''),accountValue=Object.prototype.hasOwnProperty.call(draft,'account')?draft.account:display(account,'');
