function renderQueue(){const counts={pending:0,review:0,excluded:0,removed:0,sent:0};state.tasks.forEach(t=>{const s=normalized(t.status);if(s in counts)counts[s]++;});const items=state.tasks.filter(t=>normalized(t.status)===state.tab && matchesType(t,state.type));const tabNames={pending:'Доступные',review:'На проверке',excluded:'Исключённые',removed:'Снятые',sent:'Отправленные'};const coverage=typeof state.coverage==='string'?state.coverage:'Проверка ограничена загруженной историей; полнота истории чатов не подтверждена.';
 $('queue').innerHTML=`<button class="back" id="back">← Все чаты</button><div class="queue-head"><div><div class="eyebrow">Очередь получателя · ${esc($('date').value)}</div><h2>${esc(state.chat.name)}</h2><p class="helper">${esc(platformLabel(state.chat.platform))}</p>${!state.chat.recipient?'<p class="reasons">Роль получателя не назначена. Незавершённые задачи недоступны для подготовки.</p>':''}<p class="muted">${esc(coverage)}</p><p class="helper">Обновлено: ${esc(state.loadedAt)}</p></div><button class="secondary" id="refresh-tasks">Обновить очередь</button></div><div class="type-filter"><label for="queue-type">Тип предложения</label><select id="queue-type"><option value="all" ${state.type==='all'?'selected':''}>Все</option><option value="company" ${state.type==='company'?'selected':''}>Компании</option><option value="invoice" ${state.type==='invoice'?'selected':''}>Оплата счёта</option></select></div><div class="queue-toolbar"><div class="tabs" role="tablist" aria-label="Статус задач">${Object.keys(tabNames).map(k=>`<button role="tab" aria-selected="${state.tab===k}" class="${state.tab===k?'active':''}" data-tab="${k}">${tabNames[k]} · ${counts[k]}</button>`).join('')}</div><button id="prepare" class="primary" ${state.selected.size?'':'disabled'}>Предпросмотр · ${state.selected.size}</button></div><p class="helper">Счётчики статусов показывают все типы предложений.</p><div class="selection">${state.tab==='pending'?'Выберите позиции для общего текста. Копирование не означает отправку.':'Причины и история доступны в карточках.'}</div><div class="task-list" style="margin-top:14px">${items.length?items.map(t=>taskCard(t,false)).join(''):state.type!=='all'?'<div class="empty"><strong>Нет записей выбранного типа</strong>Выберите другой тип или статус.</div>':`<div class="empty"><strong>${state.tab==='pending'?(counts.sent?'Нет доступных позиций':'Нет готовых позиций'): 'Здесь пока пусто'}</strong>${state.tab==='pending'?(counts.review?'Проверьте раздел «На проверке».':'За выбранный день подходящих задач нет или они уже отправлены.'):'Для этой категории нет задач на выбранную дату.'}</div>`}</div>`;
 $('queue-type').onchange=e=>{state.type=e.target.value;state.selected.clear();renderQueue();$('queue-type').focus();};$('back').onclick=loadChats;$('refresh-tasks').onclick=()=>loadTasks(true);$('prepare').onclick=prepare;bindMessages($('queue'));bindCardEditors($('queue'),[...state.queueCards.values()]);$('queue').querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;renderQueue();});$('queue').querySelectorAll('[data-select]').forEach(c=>c.onchange=()=>{c.checked?state.selected.add(c.dataset.select):state.selected.delete(c.dataset.select);renderQueue();});}
