$('nav-search').onclick=()=>{show('chats-view',false);show('search-view');show('history-view',false);show('review-view',false);$('nav-review').classList.remove('active');$('nav-review').removeAttribute('aria-current');$('nav-history').classList.remove('active');$('nav-search').classList.add('active');$('nav-chats').classList.remove('active');$('nav-search').setAttribute('aria-current','page');$('nav-chats').removeAttribute('aria-current');loadSources();};
$('nav-review').onclick=()=>{show('chats-view',false);show('search-view',false);show('history-view',false);show('review-view');for(const id of ['nav-chats','nav-search','nav-history']){$(id).classList.remove('active');$(id).removeAttribute('aria-current');}$('nav-review').classList.add('active');$('nav-review').setAttribute('aria-current','page');loadReview();};
$('refresh-review').onclick=loadReview;
async function loadReview(){setLoading($('review-results'));try{const data=await api('/api/review');const issues=data.document_issues||[],docs=data.documents||[];const issueLabels=reviewReasonLabels;const section=(title,entries)=>entries.length?`<div class="section-heading search-heading"><h3>${title} · ${entries.length}</h3></div>${entries.join('')}`:'';const issueCards=issues.map(x=>`<article class="task-card result"><h3>${esc(x.name||'Файл без названия')}</h3><p class="helper">${esc(x.recorded_at||'Дата записи не указана')} · ${x.company_id?'Компания № '+esc(x.company_id):'Компания не установлена'}</p><div class="reasons">${esc((x.reasons||[x.reason]).map(r=>issueLabels[r]||r).join('; '))}</div><p class="helper">${x.file_available?'Копия сохранена; связь с компанией и проверка карточки не подтверждены.':'Копия файла не сохранена: файл был недоступен.'}</p>${x.message_id?`<button class="link-button" data-message="${esc(x.message_id)}">Открыть исходное сообщение</button>`:''}</article>`);const docCards=docs.map(d=>`<article class="task-card result"><h3>${esc(d.name||'Карточка')} · ${esc(d.company||'Компания не указана')}</h3><p class="helper">ИНН ${esc(display(d.inn))} · ${esc(display(d.source_chat,'источник не указан'))} · ${esc(display(d.date,'дата не указана'))}</p><p class="helper">Статус связи с компанией: ${esc(verificationLabels[d.status]||display(d.status))}.</p><div class="reasons"><strong>Причина проверки:</strong> ${esc((d.reasons||[]).map(r=>reviewReasonLabels[r]||reasonLabels[r]||r).join('; ')||'причина не указана')}</div>${d.message_id?`<button class="link-button" data-message="${esc(d.message_id)}">Открыть исходное сообщение</button>`:''}</article>`);$('review-results').innerHTML=issues.length||docs.length?`<p class="helper">Обновлено: ${esc(stamp())}</p>`+section('Файлы без доступной копии или связи с компанией',issueCards)+section('Непроверенные карточки',docCards):'<div class="empty"><strong>Открытых вопросов по файлам нет</strong>Это относится только к загруженным данным.</div>';bindMessages($('review-results'));}catch(e){$('review-results').innerHTML='';notice(e.message,true);}}
$('nav-history').onclick=()=>{show('chats-view',false);show('search-view',false);show('review-view',false);show('history-view');for(const id of ['nav-chats','nav-search','nav-review']){$(id).classList.remove('active');$(id).removeAttribute('aria-current');}$('nav-history').classList.add('active');$('nav-history').setAttribute('aria-current','page');loadHistory();};
async function loadHistory(){setLoading($('history-results'));try{const data=await api('/api/history');const sends=data.sends||[];$('history-results').innerHTML=sends.length?sends.map(x=>`<article class="task-card result"><div class="task-title"><h3>Запись отправки № ${esc(x.id)}</h3><span class="pill sent">${esc(x.recorded_at||'')}</span></div><p class="helper">Блок № ${esc(x.block_id)} · ${x.term_id?'Вариант № '+esc(x.term_id):'Документ № '+esc(x.document_id)}</p><p class="helper">Фактическое время: ${esc(x.actual_time||'неизвестно')} · Фактический текст: ${x.actual_text?esc(x.actual_text):'неизвестен'}</p>${(x.corrections||[]).length?`<div class="reasons"><strong>Исправления записи</strong>${x.corrections.map(c=>`<p>${esc(c.recorded_at)} · ${c.cancels?'Отметка отменена: отправки не было':'Факт отправки сохранён'} · Причина: ${esc(c.reason)}</p>`).join('')}</div>`:''}<button class="link-button" data-correction="${esc(x.id)}">Исправить запись</button> · <button class="link-button" data-repeat="${esc(x.block_id)}">Записать повторную отправку</button></article>`).join(''):'<div class="empty"><strong>Записей пока нет</strong>Фактические отправки появятся здесь после подтверждения.</div>';$('history-results').querySelectorAll('[data-correction]').forEach(b=>b.onclick=()=>correction(b.dataset.correction));$('history-results').querySelectorAll('[data-repeat]').forEach(button=>button.onclick=async()=>{try{state.block=await api(`/api/blocks/${encodeURIComponent(button.dataset.repeat)}`);state.block.repeatMode=true;state.chat={id:state.block.chat_id,name:state.block.chat};renderSend();}catch(e){notice(e.message,true);}});}catch(e){$('history-results').innerHTML='';notice(e.message,true);}}
function correction(id){const close=modal('Исправить запись отправки',`<p class="muted">Запись № ${esc(id)} и исправление сохранятся в истории.</p><div class="field"><label for="correction-reason">Причина исправления</label><textarea id="correction-reason" rows="3" required></textarea></div><div class="check-row"><input type="checkbox" id="correction-cancel"><label for="correction-cancel">Отметка была ошибочной: фактической отправки не было</label></div><div id="correction-error" class="notice error" hidden></div>`,`<button class="secondary" id="cancel-correction">Отмена</button><button class="primary" id="save-correction">Сохранить исправление</button>`);$('cancel-correction').onclick=close;$('save-correction').onclick=async()=>{const reason=$('correction-reason').value.trim();if(!reason){$('correction-error').textContent='Укажите причину.';show('correction-error');return;}try{await post('/api/correction',{send_id:Number(id),reason,cancels:$('correction-cancel').checked});close();notice('Исправление записано.');loadHistory();}catch(e){$('correction-error').textContent=e.message;show('correction-error');}};}
async function loadSources(){const request=++state.sourceRequest;const date=$('date').value;const previous=$('source-filter').value;$('source-filter').disabled=true;$('source-help').textContent='Загружаем источники…';state.searchRequest++;setLoading($('search-results'),'Загружаем предложения…');try{const data=await api(`/api/sources?date=${encodeURIComponent(date)}`);if(request!==state.sourceRequest)return;const sources=data.sources||[];$('source-filter').innerHTML='<option value="">Все источники</option>'+sources.map(x=>`<option value="${esc(x.id)}">${esc(x.name)} · ${esc(platformLabel(x.platform))} · ${esc(x.count)}</option>`).join('');if(sources.some(x=>String(x.id)===previous))$('source-filter').value=previous;$('source-filter').disabled=false;$('source-help').textContent=sources.length?'Источники, приславшие предложения в выбранный день; число — количество вариантов.':'За эту дату активных предложений от источников нет.';await search();}catch(e){if(request!==state.sourceRequest)return;$('source-filter').innerHTML='<option value="">Все источники</option>';$('source-filter').disabled=true;$('source-help').textContent='Не удалось загрузить источники.';$('search-results').innerHTML='';notice(e.message,true);}}
